<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});useHead({title:'Intervenants'})
type Intervenor={id:string;firstName:string;lastName:string;email:string;phone:string|null;specialty:string|null;status:string;siret:string|null;city:string|null;country:string|null;user:{id:string;status:string;mfaEnabled:boolean}|null;_count:{projectLinks:number;documents:number;accountingDocuments:number;reports:number}}
const {data,error,refresh}=await useFetch<ApiSuccess<Intervenor[]>>('/api/intervenors');const items=computed(()=>data.value?.data??[])
</script>
<template><div><div class="page-head"><div><h1>Intervenants</h1><p>Prestataires et professionnels mobilisés sur les actions.</p></div><button class="btn btn-secondary" type="button" @click="refresh()">Actualiser</button></div><div v-if="error" class="alert alert-error">Impossible de charger les intervenants.</div><div v-else-if="!items.length" class="empty-state">Aucun intervenant accessible.</div><div v-else class="table-wrap"><table><thead><tr><th>Intervenant</th><th>Spécialité</th><th>Localisation</th><th>Missions</th><th>Documents</th><th>Compte</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.firstName }} {{ item.lastName }}</strong><br><small>{{ item.email }}</small></td><td>{{ item.specialty || '—' }}</td><td>{{ [item.city,item.country].filter(Boolean).join(', ') || '—' }}</td><td>{{ item._count.projectLinks }}</td><td>{{ item._count.documents + item._count.accountingDocuments }}</td><td><span v-if="item.user" class="badge" :class="item.user.mfaEnabled?'':'badge-warning'">{{ item.user.mfaEnabled ? 'MFA actif' : 'MFA à configurer' }}</span><span v-else class="badge badge-muted">Sans compte</span></td></tr></tbody></table></div></div></template>
